from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        # quick impossibility check: max possible |alternating sum| is bounded
        max_abs = 12 * ((n + 1) // 2)
        if k > max_abs or k < -max_abs:
            return -1

        OVER = limit + 1  # sentinel for product exceeding limit

        # state: (alt_sum, parity_of_length, product)
        # parity 0 -> even length -> next element added with +
        # parity 1 -> odd length  -> next element added with -
        states = set()

        for i, x in enumerate(nums):
            remaining_after = n - i - 1  # elements after this one
            # max change to sum possible with remaining elements
            slack = 12 * remaining_after

            add = set()
            # start a new subsequence with x (index 0, positive)
            p0 = x if x <= limit else OVER
            if abs(x - k) <= slack:
                add.add((x, 1, p0))

            for (s, p, pr) in states:
                if p == 0:
                    ns = s + x
                else:
                    ns = s - x
                if abs(ns - k) > slack:
                    continue
                npr = pr * x
                if npr > limit:
                    npr = OVER
                add.add((ns, p ^ 1, npr))

            states |= add

            # prune states that can no longer reach k (with remaining elements)
            if add:
                states = {(s, p, pr) for (s, p, pr) in states if abs(s - k) <= slack}

        ans = -1
        for (s, p, pr) in states:
            if s == k and pr <= limit and pr > ans:
                ans = pr
        return ans

