import numpy as np


class Solution:
    _G = None

    @classmethod
    def _precompute(cls):
        if cls._G is not None:
            return cls._G
        G = {}
        for s in range(1, 82):
            # T[k][sum][pm] = number of length-k strings over digits 1..9
            # with digit sum = sum and digit product mod s = pm
            T = np.zeros((10, s + 1, s), dtype=np.int64)
            T[0, 0, 1 % s] = 1
            for k in range(1, 10):
                for d in range(1, 10):
                    if d > s:
                        continue
                    map_d = (np.arange(s) * d) % s
                    rows = np.arange(d, s + 1)
                    np.add.at(T[k], (rows[:, None], map_d[None, :]), T[k - 1][:s + 1 - d])
            # B[a][pm] = 1 if (a*pm) % s == 0
            ar = np.arange(s)
            B = ((ar[:, None] * ar[None, :]) % s == 0).astype(np.int64)
            # G[k][sum][a] = sum over pm with (a*pm)%s==0 of T[k][sum][pm]
            G[s] = T @ B
        cls._G = G
        return G

    def _f(self, n: int) -> int:
        if n <= 0:
            return 0
        digs = list(map(int, str(n)))
        m = len(digs)

        # count numbers in [1, n] with all nonzero digits
        nz = sum(9 ** L for L in range(1, m))
        ok = True
        for i, d in enumerate(digs):
            nz += max(d - 1, 0) * 9 ** (m - 1 - i)
            if d == 0:
                ok = False
                break
        if ok:
            nz += 1

        res = n - nz  # numbers containing a zero digit are always beautiful

        # check n itself (if all nonzero digits)
        if ok:
            ssum = sum(digs)
            prod = 1
            for d in digs:
                prod *= d
            if prod % ssum == 0:
                res += 1

        G = self._precompute()
        max_s = min(81, 9 * m)
        for s in range(1, max_s + 1):
            Gs = G[s]
            a1 = 1 % s
            # fully free lengths < m
            for L in range(1, m):
                res += int(Gs[L][s][a1])
            # tight walk for length m (excluding n itself, handled above)
            sum0 = 0
            pm0 = 1 % s
            for i in range(m):
                d = digs[i]
                k = m - 1 - i
                for dd in range(1, d):
                    rem = s - sum0 - dd
                    if rem >= 0:
                        res += int(Gs[k][rem][(pm0 * dd) % s])
                if d == 0 or sum0 + d > s:
                    break
                sum0 += d
                pm0 = (pm0 * d) % s
        return res

    def beautifulNumbers(self, l: int, r: int) -> int:
        return self._f(r) - self._f(l - 1)

