from collections import deque

def main():
    sys.setrecursionlimit(300000)
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    K = int(data[idx]); idx += 1
    edges = []
    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        edges.append((u, v))

    INF = 10**7

    class Dinic:
        def __init__(self, n):
            self.n = n
            self.g = [[] for _ in range(n)]
        def add_edge(self, u, v, cap):
            self.g[u].append([v, cap, len(self.g[v])])
            self.g[v].append([u, 0, len(self.g[u]) - 1])
        def bfs(self, s, t):
            self.level = [-1] * self.n
            q = deque([s]); self.level[s] = 0
            while q:
                u = q.popleft()
                for e in self.g[u]:
                    if e[1] > 0 and self.level[e[0]] < 0:
                        self.level[e[0]] = self.level[u] + 1
                        q.append(e[0])
            return self.level[t] >= 0
        def dfs(self, u, t, f):
            if u == t:
                return f
            while self.it[u] < len(self.g[u]):
                e = self.g[u][self.it[u]]
                v = e[0]
                if e[1] > 0 and self.level[v] == self.level[u] + 1:
                    d = self.dfs(v, t, min(f, e[1]))
                    if d > 0:
                        e[1] -= d
                        self.g[v][e[2]][1] += d
                        return d
                self.it[u] += 1
            return 0
        def maxflow(self, s, t, limit):
            flow = 0
            while flow < limit and self.bfs(s, t):
                self.it = [0] * self.n
                while flow < limit:
                    f = self.dfs(s, t, limit - flow)
                    if f == 0:
                        break
                    flow += f
            return flow

    # Answer D: exist integer potentials l_v with l_1=0, l_N=D,
    # l_v <= l_u + 1 for every edge (u,v), and #edges with l_v = l_u+1 <= K.
    # Min-cut (Ishikawa) construction with boolean x_{v,i} = [l_v >= i].
    best = 0
    maxD = min(K, N - 1)
    for D in range(1, maxD + 1):
        # nodes: S=0, T=1, (v,i) -> 2 + (v-1)*D + (i-1)  for v in 1..N, i in 1..D
        def nid(v, i):
            return 2 + (v - 1) * D + (i - 1)
        n_nodes = 2 + N * D
        din = Dinic(n_nodes)
        S, T = 0, 1
        # monotonicity: x_{v,i+1}=1 => x_{v,i}=1
        for v in range(1, N + 1):
            for i in range(1, D):
                din.add_edge(nid(v, i + 1), nid(v, i), INF)
        # l_1 = 0 : x_{1,1} = 0
        din.add_edge(nid(1, 1), T, INF)
        # l_N = D : x_{N,D} = 1
        din.add_edge(S, nid(N, D), INF)
        # graph edges
        for (u, v) in edges:
            # cost 1 per unit of max(0, l_v - l_u): edges (v,i)->(u,i) cap 1
            for i in range(1, D + 1):
                din.add_edge(nid(v, i), nid(u, i), 1)
            # hard constraint l_v <= l_u + 1: x_{v,i+1}=1 => x_{u,i}=1
            for i in range(1, D):
                din.add_edge(nid(v, i + 1), nid(u, i), INF)
        flow = din.maxflow(S, T, K + 1)
        if flow <= K:
            best = D
        else:
            break

    print(best)

