from itertools import groupby

def parse_pairs(s):
    pairs = []
    a = 0
    for ch, g in groupby(s):
        l = sum(1 for _ in g)
        if ch == '0':
            a = l
        else:
            pairs.append((a, l))
            a = 0
    if a:
        pairs.append((a, 0))
    return pairs

def normal_form(s, X, Y):
    stack = []   # list of [zeros, ones]
    blocks = []  # ascending indices of blocking pairs (zeros % X != 0, or zeros==0 at front)
    for (a0, b) in parse_pairs(s):
        a = a0
        if stack and stack[-1][1] == 0:
            a += stack[-1][0]
            stack.pop()
        idx = len(stack)
        stack.append([a, b])
        if (a % X != 0) or a == 0:
            blocks.append(idx)
        if a >= X and b >= Y:
            P = (b // Y) * Y
            s0 = b - P
            r = a % X
            if r != 0:
                # pile stops inside its own zero run: 0^r 1^P 0^(a-r) 1^s0
                stack[-1] = [r, P]
                stack.append([a - r, s0])
            else:
                stack[-1][1] = s0
                if not blocks:
                    # pile passes everything, lands at string front
                    stack.insert(0, [0, P])
                    blocks.append(0)
                else:
                    j = blocks[-1]
                    aj, bj = stack[j]
                    if aj < X:
                        # merge-type blocking: pile joins this one-run
                        stack[j][1] = bj + P
                    else:
                        # split-type: aj > X with aj % X = rj != 0
                        rj = aj % X
                        stack[j] = [rj, P]
                        stack.insert(j + 1, [aj - rj, bj])
    # canonical RLE (drop zero-length runs, merge adjacent same-char runs)
    out = []
    for a, b in stack:
        if a:
            if out and out[-1][0] == 0:
                out[-1][1] += a
            else:
                out.append([0, a])
        if b:
            if out and out[-1][0] == 1:
                out[-1][1] += b
            else:
                out.append([1, b])
    return out

