from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # bucket pairs by their larger element
        by_b = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            by_b[b].append(a)

        top1 = 0  # largest 'a' among active pairs (with multiplicity)
        top2 = 0  # second largest 'a' among active pairs
        base = 0
        bonus = [0] * (n + 1)  # bonus[v] = total gain if we remove the pair whose smaller element is v (when it's the unique max)

        for r in range(1, n + 1):
            for a in by_b[r]:
                if a >= top1:
                    top2 = top1
                    top1 = a
                elif a > top2:
                    top2 = a
            base += r - top1
            # removing the pair providing top1 would let f drop to top2 at this r
            bonus[top1] += top1 - top2

        return base + max(bonus)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        s2 = str2.encode()
        word = bytearray(L)      # 0 = unset
        fixed = bytearray(L)     # 1 = fixed
        filled_end = 0           # end (exclusive) of the last T-filled interval

        # Step 1: apply T constraints
        for i in range(n):
            if str1[i] == 'T':
                if i < filled_end:
                    # overlap with previously filled region [i, min(i+m, filled_end))
                    e = min(i + m, filled_end)
                    if word[i:e] != s2[:e - i]:
                        return ""
                    if i + m > filled_end:
                        word[filled_end:i + m] = s2[filled_end - i:]
                        fixed[filled_end:i + m] = b'\x01' * (i + m - filled_end)
                        filled_end = i + m
                else:
                    word[i:i + m] = s2
                    fixed[i:i + m] = b'\x01' * m
                    filled_end = i + m

        # Step 2: fill free positions with 'a'
        for p in range(L):
            if not fixed[p]:
                word[p] = 97  # 'a'

        # Step 3: process F constraints left to right
        for i in range(n):
            if str1[i] == 'F':
                if word[i:i + m] == s2:
                    # must break this match: rightmost free position in [i, i+m)
                    j = fixed.rfind(b'\x00', i, i + m)
                    if j < 0:
                        return ""
                    # word[j] was 'a' (it matched str2[j-i]), smallest different char is 'b'
                    word[j] = 98  # 'b'
                    fixed[j] = 1

        return word.decode()

