class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**16  # anything above this dwarfs k <= 1e15
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)

        odds = list(range(1, n + 1, 2))   # sorted available odds
        evens = list(range(2, n + 1, 2))  # sorted available evens

        res = []
        # required parity for current position: 1 = odd, 0 = even, None = free (first pos, n even)
        if n % 2 == 1:
            parity = 1
        else:
            parity = None

        for i in range(n):
            if parity is None:
                # first position when n is even: candidates are all numbers in numeric order
                candidates = sorted(odds + evens)
            elif parity == 1:
                candidates = list(odds)
            else:
                candidates = list(evens)

            chosen = None
            for v in candidates:
                if v % 2 == 1:
                    o2 = len(odds) - 1
                    e2 = len(evens)
                else:
                    o2 = len(odds)
                    e2 = len(evens) - 1
                cnt = fact[o2] * fact[e2]
                if k > cnt:
                    k -= cnt
                else:
                    chosen = v
                    break

            if chosen is None:
                return []

            res.append(chosen)
            if chosen % 2 == 1:
                odds.remove(chosen)
                parity = 0  # next must be even
            else:
                evens.remove(chosen)
                parity = 1  # next must be odd

        return res

