class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        P = 4 * s
        pos = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == s:
                t = s + y
            elif y == s:
                t = 2 * s + (s - x)
            else:  # x == 0
                t = 3 * s + (s - y)
            pos.append(t)
        pos.sort()
        n = len(pos)
        p2 = pos + [t + P for t in pos]
        N2 = 2 * n

        def feasible(m):
            # two-pointer next jump: first index j with p2[j] >= p2[i] + m
            nxt = [N2] * (N2 + 1)
            j = 0
            for i in range(N2):
                target = p2[i] + m
                if j < i + 1:
                    j = i + 1
                while j < N2 and p2[j] < target:
                    j += 1
                nxt[i] = j
            nxt_local = nxt
            cur = list(range(n))
            for _ in range(k - 1):
                cur = [nxt_local[c] for c in cur]
            lim = P - m
            for i in range(n):
                jj = cur[i]
                if jj < N2 and p2[jj] - p2[i] <= lim:
                    return True
            return False

        lo, hi = 1, P // k
        ans = 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

