        order.append(u)
        for w in adj[u]:
            if not visited[w]:
                visited[w] = True
                parent[w] = u
                q.append(w)

    # cdown[v]: contribution of v to its parent side edge:
    # max(1, 1 + top3 sum of children contributions) if v has >=3 children else 1
    cdown = [1] * (n + 1)
    for u in reversed(order):
        ch = []
        pu = parent[u]
        for w in adj[u]:
            if w != pu:
                ch.append(cdown[w])
        if len(ch) >= 3:
            ch.sort(reverse=True)
            cdown[u] = 1 + ch[0] + ch[1] + ch[2]
        else:
            cdown[u] = 1

    cup = [1] * (n + 1)  # contribution from parent side toward v
    ans = -1
    for u in order:
        pu = parent[u]
        vals = []
        if u != 1:
            vals.append(cup[u])
        for w in adj[u]:
            if w != pu:
                vals.append(cdown[w])
        deg = len(adj[u])
        if deg >= 4:
            s = sorted(vals, reverse=True)
