class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        a, b, c = p[:i1], p[i1 + 1:i2], p[i2 + 1:]
        n = len(s)

        def find_all(pat):
            m = len(pat)
            if m == 0:
                return list(range(n + 1))
            # KMP failure function
            f = [0] * m
            k = 0
            for i in range(1, m):
                while k and pat[i] != pat[k]:
                    k = f[k - 1]
                if pat[i] == pat[k]:
                    k += 1
                f[i] = k
            res = []
            k = 0
            for i in range(n):
                ch = s[i]
                while k and ch != pat[k]:
                    k = f[k - 1]
                if ch == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = f[k - 1]
            return res

        A = find_all(a)
        B = find_all(b)
        C = find_all(c)
        if not A or not B or not C:
            return -1

        lenA, lenB, lenC = len(a), len(b), len(c)
        INF = float('inf')
        ans = INF
        pa = -1  # index into A of best (largest) a-start <= j - lenA
        ic = 0   # index into C of smallest c-start >= j + lenB
        lA, lC = len(A), len(C)

        for j in B:
            limit = j - lenA
            while pa + 1 < lA and A[pa + 1] <= limit:
                pa += 1
            if pa == -1:
                continue
            need = j + lenB
            while ic < lC and C[ic] < need:
                ic += 1
            if ic == lC:
                break
            cand = C[ic] + lenC - A[pa]
            if cand < ans:
                ans = cand

        return ans if ans != INF else -1

