from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def check(t: int) -> bool:
            # can we make min gameScore >= t within m moves?
            if t == 0:
                return True
            moves = 0
            prev = 0  # visits already credited to current position from oscillation
            for i in range(n):
                p = points[i]
                need = (t + p - 1) // p - prev  # remaining visits needed here
                if i == n - 1 and need <= 0:
                    # last position already satisfied, no need to step on it
                    break
                if need < 1:
                    need = 1  # must pass through at least once
                # step into position (1 move) + (need-1) oscillations (2 moves each)
                moves += 2 * need - 1
                if moves > m:
                    return False
                prev = need - 1  # oscillations already visited next position need-1 times
            return moves <= m

        lo, hi = 0, 0
        # upper bound: max visits to any single cell is about (m+1)//2 + 1
        max_visits = (m + 1) // 2 + 2
        hi = min(p * max_visits for p in points)

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

