    svals = sorted(set(xs))
    m = len(svals)
    pos_of = {v: i for i, v in enumerate(svals)}
    size = 1
    while size < m:
        size <<= 1
    tr = [0] * (size + 1)
    prev = 0
    for i, v in enumerate(svals, 1):
        tr[i] = v - prev
        prev = v
    for i in range(1, size + 1):
        j = i + (i & -i)
        if j <= size:
            tr[j] += tr[i]
    klist = []
    k = size
    while k:
        klist.append(k)
        k >>= 1
    curmin = svals[0]
    curmax = svals[-1]
    Ls = list(map(int, cs[0::2]))
    Rs = list(map(int, cs[1::2]))
    for L, R in zip(Ls, Rs):
        if R < curmin or L > curmax:
            continue
        if L <= curmin:
            i = 1
        else:
            pos = 0; s = 0
            for k in klist:
                np_ = pos + k
                sv2 = s + tr[np_]
                if sv2 < L:
                    pos = np_; s = sv2
            i = pos + 1
        if R >= curmax:
            j = m
        else:
            t2 = R + 1
            pos = 0; s = 0
            for k in klist:
                np_ = pos + k
                sv2 = s + tr[np_]
                if sv2 < t2:
                    pos = np_; s = sv2
            j = pos
        if i > j:
            continue
        ii = i
        while ii <= size:
            tr[ii] += 1
            ii += ii & -ii
        if j < m:
            jj = j + 1
            while jj <= size:
                tr[jj] -= 1
                jj += jj & -jj
        if i == 1:
            curmin += 1
        if j == m:
            curmax += 1
    # recover difference array from fenwick
    for i in range(size, 0, -1):
        j = i + (i & -i)
        if j <= size:
            tr[j] -= tr[i]
    vals = list(accumulate(tr))  # vals[idx] = final value of sorted position idx (1-based)
    out = []
    ap = out.append
    for x in xs:
        ap(vals[pos_of[x] + 1])
    sys.stdout.write('\n'.join(map(str, out)))

