def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); M = int(data[1]); A = int(data[2]); B = int(data[3])
    bads = []
    idx = 4
    for _ in range(M):
        L = int(data[idx]); R = int(data[idx+1]); idx += 2
        bads.append((L, R))

    if A == B:
        if (N - 1) % A != 0:
            print("No"); return
        rem = 1 % A
        for L, R in bads:
            j = L + ((rem - L) % A)
            if j <= R:
                print("No"); return
        print("Yes"); return

    # build free segments
    segs = []
    cur = 1
    for L, R in bads:
        segs.append((cur, L - 1))
        cur = R + 1
    segs.append((cur, N))

    glist = deque()  # reachable intervals (sorted, disjoint)
    last_result = []
    for lo, hi in segs:
        if lo > hi:
            continue
        wl = lo - B
        # prune intervals too far left to matter anymore
        while glist and glist[0][1] < wl:
            glist.popleft()
        seeds = []
        if lo == 1:
            seeds.append((1, 1))
        for pl, pr in glist:
            a = max(pl, wl); b = min(pr, lo - 1)
            if a <= b:
                ta = max(a + A, lo); tb = min(b + B, hi)
                if ta <= tb:
                    seeds.append((ta, tb))
        if not seeds:
            last_result = []
            continue
        res = []
        for a, b in seeds:
            k = 0
            while True:
                l = a + k * A
                if l > hi:
                    break
                # if step-k interval touches/overlaps step-(k+1) interval,
                # everything from l to hi is reachable
                if a + (k + 1) * A <= b + k * B + 1:
                    res.append((l, hi))
                    break
                res.append((l, min(b + k * B, hi)))
                k += 1
        res.sort()
        merged = []
        for l, r in res:
            if merged and l <= merged[-1][1] + 1:
                if r > merged[-1][1]:
                    merged[-1] = (merged[-1][0], r)
            else:
                merged.append((l, r))
        for iv in merged:
            glist.append(iv)
        last_result = merged

    ok = any(l <= N <= r for l, r in last_result)
    print("Yes" if ok else "No")

