def main():
    data = sys.stdin.read().split()
    K = int(data[0])
    S = data[1]
    T = data[2]
    n, m = len(S), len(T)

    if abs(n - m) > K:
        print("No")
        return

    def lcp(i, j):
        # longest common prefix of S[i:] and T[j:]
        mx = min(n - i, m - j)
        if mx <= 0 or S[i] != T[j]:
            return 0
        length = 1
        while length < mx:
            nxt = min(length * 2, mx)
            if S[i+length:i+nxt] == T[j+length:j+nxt]:
                length = nxt
            else:
                lo, hi = length, nxt - 1
                while lo < hi:
                    mid = (lo + hi + 1) // 2
                    if S[i+lo:i+mid] == T[j+lo:j+mid]:
                        lo = mid
                    else:
                        hi = mid - 1
                return lo
        return length

    size = 2 * K + 3
    NEG = -10
    prev = [NEG] * size
    target_d = m - n

    for e in range(K + 1):
        cur = [NEG] * size
        for d in range(-e, e + 1):
            if d > m or -d > n:
                continue
            if e == 0:
                row = 0
            else:
                idx = d + K + 1
                a = prev[idx] + 1        # substitution
                b = prev[idx + 1] + 1    # deletion from S
                c = prev[idx - 1]        # insertion into S
                row = a
                if b > row:
                    row = b
                if c > row:
                    row = c
            if row < 0:
                continue
            # clamp
            if row > n:
                row = n
            if row + d > m:
                row = m - d
            if row < 0:
                continue
            j = row + d
            if row < n and j < m:
                row += lcp(row, j)
            idx = d + K + 1
            if row > cur[idx]:
                cur[idx] = row
            if d == target_d and row >= n:
                print("Yes")
                return
        prev = cur

    print("No")

