class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # cost for m = 1: make alternating
        c = sum(1 for i, ch in enumerate(s) if int(ch) != i % 2)
        cost1 = min(c, n - c)
        if cost1 <= numOps:
            return 1

        # runs
        runs = []
        cnt = 1
        for i in range(1, n):
            if s[i] == s[i-1]:
                cnt += 1
            else:
                runs.append(cnt)
                cnt = 1
        runs.append(cnt)

        def feasible(m):
            # each run of length L needs L // (m+1) flips
            return sum(L // (m + 1) for L in runs) <= numOps

        lo, hi = 2, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
